<?php require_once dirname(__DIR__,2).'/bootstrap.php';$me=require_auth();$uid=(int)$me['id'];$p=db();if(request_method()==='POST'){$d=request_json();$other=(int)($d['userId']??0);$action=$d['action']??'';if(!in_array($action,['accept','reject'],true))json_response(['message'=>'Geçersiz karar.'],400);try{$p->beginTransaction();if(!v17_query('SELECT 1 FROM follow_requests WHERE requester_user_id=? AND target_user_id=? FOR UPDATE',[$other,$uid])->fetchColumn())json_response(['message'=>'İstek zaten işlenmiş.'],409);if($action==='accept'){v17_query('INSERT IGNORE INTO follows(follower_user_id,followed_user_id) VALUES (?,?)',[$other,$uid]);create_notification($other,$uid,'follow_accepted','Takip isteğin onaylandı',$me['display_name'].' isteğini onayladı.','./channel.php?id='.$uid);}v17_query('DELETE FROM follow_requests WHERE requester_user_id=? AND target_user_id=?',[$other,$uid]);v17_query("UPDATE notifications SET is_read=1 WHERE user_id=? AND actor_user_id=? AND type='follow_request'",[$uid,$other]);$p->commit();}catch(Throwable $e){if($p->inTransaction())$p->rollBack();json_response(['message'=>'İstek işlenemedi.'],500);}}$rows=v17_query('SELECT u.* FROM follow_requests f JOIN users u ON u.id=f.requester_user_id WHERE f.target_user_id=? ORDER BY f.created_at DESC LIMIT 100',[$uid])->fetchAll();json_response(['requests'=>array_map('v17_person',$rows),'message'=>'İstek güncellendi.']);